"""Per-point actual-load and body-motion diagnostics; never use released anchor as task loss."""
import json,gzip,sys,math
from pathlib import Path
import numpy as np

def analyze(path):
 with gzip.open(path,'rt') as f:e=json.load(f)
 rows=e['physics'];s=e['condition'];out=dict(label=e['label'],condition=s,boundary=e['boundary'],phases={});ctrl=e['control'];stop=s.get('stop_time');move_end=stop if stop is not None else s['onset']+s['ramp'];hold_start=stop+s.get('deceleration',0) if stop is not None else move_end
 for name,select in [('pre',lambda r:not r['active'] and r['force_time']<s['release']),('move',lambda r:r['active'] and r['force_time']<move_end),('decelerate',lambda r:r['active'] and move_end<=r['force_time']<hold_start),('hold',lambda r:r['active'] and r['force_time']>=hold_start),('contact',lambda r:r['active']),('recover',lambda r:not r['active'] and r['force_time']>=s['release'])]:
  rr=[r for r in rows if select(r)]
  if not rr:continue
  root=np.array([r['root'] for r in rr]);q=np.array([r['qpos'][7:] for r in rr]);dq=np.array([r['qvel'][6:] for r in rr]);pts={}
  for slot in sorted({c['slot'] for r in rr for c in r['contacts']}):
   cs=[c for r in rr for c in r['contacts'] if c['slot']==slot];F=np.array([c['force'] for c in cs]);pos=np.array([c['point'] for c in cs]);err=np.array([np.array(c['anchor'])-c['point'] for c in cs]);pts[slot]=dict(link=cs[0]['link'],local=cs[0]['local'],force_xyz_mean=F.mean(0).tolist(),force_xyz_rms=np.sqrt((F*F).mean(0)).tolist(),force_rms=float(np.sqrt((F*F).sum(1).mean())),cap_fraction=float((np.linalg.norm(F,axis=1)>=cs[0]['cap']-.001).mean()),error_xyz_mean_cm=(err.mean(0)*100).tolist() if name in ['move','decelerate','hold','contact'] else None,error_rms_cm=float(np.sqrt((err*err).sum(1).mean())*100) if name in ['move','decelerate','hold','contact'] else None,point_displacement_cm=((pos[-1]-pos[0])*100).tolist(),yaw_moment_mean=float(np.mean([c['yaw_moment_com'] for c in cs])),work_j=float(sum(c['power']*.005 for c in cs)))
  yaw={}
  for part in ['pelvis','torso']:
   M=np.array([r[part+'_matrix'] for r in rr]);a=np.unwrap(np.arctan2(M[:,1,0],M[:,0,0]));target=np.array([r['target_yaw'] for r in rr]);err=np.arctan2(np.sin(target-a),np.cos(target-a));yaw[part]=dict(start_deg=float(np.degrees(a[0])),end_deg=float(np.degrees(a[-1])),range_deg=np.degrees([a.min(),a.max()]).tolist(),target_end_deg=float(np.degrees(target[-1])),error_rms_deg=float(np.degrees(np.sqrt(np.mean(err**2)))) if name in ['move','decelerate','hold','contact'] else None)
  cc=[c for c in ctrl if rr[0]['force_time']-.001<=c['time']<=rr[-1]['force_time']+.001];targets=np.array([c['q_PD'] for c in cc]);steps=np.degrees(np.abs(np.diff(targets,axis=0))) if len(cc)>1 else np.zeros((1,29));mom=np.array([r['net_yaw_moment_com'] for r in rr]);feet=np.array([r['feet_xyz'] for r in rr])
  bodies={k:np.array([r['body_positions'][k] for r in rr]) for k in rr[0]['body_positions']};body_motion={k:dict(delta_cm=((v[-1]-v[0])*100).tolist(),path_cm=float(np.linalg.norm(np.diff(v,axis=0),axis=1).sum()*100),relative_root_delta_cm=(((v-root)[-1]-(v-root)[0])*100).tolist()) for k,v in bodies.items()}
  out['phases'][name]=dict(body_motion=body_motion,seconds=len(rr)*.005,points=pts,yaw=yaw,root_delta_cm=((root[-1]-root[0])*100).tolist(),root_path_cm=float(np.linalg.norm(np.diff(root,axis=0),axis=1).sum()*100),root_velocity_rms=float(np.sqrt(np.mean(np.sum(np.array([r['qvel'][:3] for r in rr])**2,axis=1)))),net_yaw_moment_mean=float(mom.mean()),net_yaw_moment_rms=float(np.sqrt((mom*mom).mean())),sum_force_norm_rms=float(np.sqrt(np.mean([r['sum_force_norm']**2 for r in rr]))),net_force_rms=float(np.sqrt(np.mean([np.dot(r['force'],r['force']) for r in rr]))),work_j=sum(r['external_power']*.005 for r in rr),positive_work_j=sum(max(0,r['external_power'])*.005 for r in rr),negative_work_j=sum(min(0,r['external_power'])*.005 for r in rr),root_height_min=float(root[:,2].min()),tilt_max=max(r['tilt_deg'] for r in rr),no_support_fraction=float(np.mean([not any(r['support']) for r in rr])),foot_contact_load_n_mean=np.mean([r['foot_normal_force_n'] for r in rr],axis=0).tolist(),foot_displacement_cm=((feet[-1]-feet[0])*100).tolist(),foot_path_cm=(np.linalg.norm(np.diff(feet,axis=0),axis=2).sum(0)*100).tolist(),contact_slip_max=max(r['contact_tangent_speed_max_mps'] for r in rr),qPD_step_max_deg=float(steps.max()),qPD_step_p99_deg=float(np.quantile(steps,.99)),actual_q_step_max_deg=float(np.degrees(np.abs(np.diff(q,axis=0))).max()) if len(q)>1 else 0.,actual_dq_max=float(np.abs(dq).max()),torque_saturation_mean=float(np.mean([r['torque_saturation'] for r in rr])),joint_limit_max=max(r['joint_limit_excess_max_rad'] for r in rr))
 return out
if __name__=='__main__':
 d=Path(sys.argv[1]);out={p.stem:analyze(p) for p in sorted(d.glob('*.json.gz')) if not p.name.endswith('-queries.json.gz')};(d/'geometry-metrics.json').write_text(json.dumps(out,indent=2));print('analyzed',len(out))
